-- Electronics sample dataset v1. Transaction and backup are managed by ElectronicsSeed.
set local lock_timeout = '10s';
set local statement_timeout = '90s';
create temp table seed_actor on commit drop as select id from public.profiles where role='admin' and is_active order by id limit 1;
do $$ begin if not exists(select 1 from seed_actor) then raise exception 'Active admin profile required'; end if; end $$;
do $checks$ begin
if (select count(*) from public.products)<>50 or (select count(*) from public.orders)<>100 or (select count(*) from public.customers)<>40 then raise exception 'Unexpected dataset counts'; end if;
if exists(select 1 from public.orders o where o.subtotal<>(select sum(i.line_total) from public.order_items i where i.order_id=o.id) or o.total<>o.subtotal+o.tax+o.shipping_fee) then raise exception 'Order money mismatch'; end if;
if exists(select 1 from public.order_items where line_total<>quantity*unit_price or unit_cost is null) then raise exception 'Line money mismatch'; end if;
if exists(select 1 from public.inventory_items i where i.reserved<>coalesce((select sum(r.remaining_quantity) from public.inventory_reservations r where r.warehouse_id=i.warehouse_id and r.product_id=i.product_id and r.state='reserved'),0)) then raise exception 'Reservations mismatch'; end if;
if exists(select 1 from public.inventory_items i where i.stock<>coalesce((select sum(t.quantity_delta) from public.stock_transactions t where t.warehouse_id=i.warehouse_id and t.product_id=i.product_id and t.type in ('inbound','outbound','adjustment','return_in','transfer_in','transfer_out')),0)) then raise exception 'Physical stock mismatch'; end if;
if exists(select 1 from public.inventory_reservations r join public.orders o on o.id=r.order_id where (o.status in ('pending','confirmed','processing') and r.state<>'reserved') or (o.status in ('shipped','delivered') and r.state<>'committed') or (o.status='cancelled' and r.state<>'released')) then raise exception 'Reservation state mismatch'; end if;
end $checks$;
do $validate$
begin
 if (select count(*) from public.inventory_items)<>150
   or (select count(*) from public.order_items)<>189
   or (select count(*) from public.order_fee_breakdowns)<>109
   or (select count(*) from public.return_requests)<>8
   or (select count(*) from public.channel_sku_mappings)<>200 then
   raise exception 'Unexpected dependent row counts';
 end if;
 if exists(
  select 1 from public.return_items ri
  join public.order_items oi on oi.id=ri.order_item_id
  join public.return_requests r on r.id=ri.return_request_id
  where r.order_id<>oi.order_id or ri.quantity>oi.quantity
 ) then raise exception 'Invalid return quantities or order linkage'; end if;
 if exists(
  select 1 from public.orders o
  where (o.status in ('pending','confirmed','processing') and exists(select 1 from public.order_fee_breakdowns f where f.order_id=o.id))
   or (select count(*) from public.order_status_log h where h.order_id=o.id)=0
 ) then raise exception 'Order fees/history inconsistent'; end if;
 if (select count(*) from public.inventory_operation_receipts where operation='reserve')<>189 then
   raise exception 'Missing reserve receipts';
 end if;
end $validate$;